package com.aicharacter.v3;
/** Active autonomy evaluates at meaningful intervals, then executes a persistent plan instead of rerolling every frame. */
public final class HaruAutonomyEngine {private static long nextDecisionAt=0;private HaruAutonomyEngine(){}
 public static void tick(WorldState s,float dt){BodyRhythmEngine.advanceSeconds(s,dt);s.environment.updateForTime(s.worldMinutes);s.emotion.decay(Math.pow(.997,dt));s.mood.decay(Math.pow(.9997,dt));long now=System.currentTimeMillis();if(BodyRhythmEngine.shouldRemainAsleep(s))return;if(BodyRhythmEngine.isSleeping(s))s.haruActivity="waking slowly";if(s.girlTravel.active)return;if(now<nextDecisionAt)return;nextDecisionAt=now+12000;if("PAUSED".equals(s.planState.status)){if(PlanExecutor.resume(s,now))return;}PlanIntegrityChecker.check(s,now);PlanReconsiderationEngine.Result rr=PlanReconsiderationEngine.evaluate(s,now);if(s.planState.active()&&!rr.reconsider())return;if(rr.reconsider()){PlanExecutor.applyDecision(s,rr,now);if(s.planState.active())return;}LifeDecision d=LifeDecisionEngine.choose(s,now);OfflineLifeEngine.beginDecision(s,d,now);s.haruMood=s.mood.label();}
}
